func (h *Handler) issuerFor(r *http.Request) string {
	if h.issuer != "" {
		return h.issuer
	}
	if h.provider != nil {
		return strings.TrimRight(h.provider.IssuerFromRequest(r), "/")
	}
	return ""
}
